import{_ as p,a0 as u,w as s,s as a,ao as r,I as e,x as n,a1 as l,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse(`{"title":"为什么我们不应该接受低劣的Linux移植游戏 | LCTT x X-CMD","titleTemplate":false,"description":"为什么我们不应该接受低劣的Linux移植游戏 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么我们不应该接受低劣的Linux移植游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么我们不应该接受低劣的Linux移植游戏 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140528 Why We Shouldn't Accept Bad Linux Ports","title":"为什么我们不应该接受低劣的Linux移植游戏","tag":"201406","desc":""},"relativePath":"201406/20140528 Why We Shouldn't Accept Bad Linux Ports.md","filePath":"[post].md"}`),x={name:"201406/20140528 Why We Shouldn't Accept Bad Linux Ports.md"};function d(m,t,L,w,T,f){const i=u("Link");return s(),a("div",null,[t[14]||(t[14]=r('<h1 id="为什么我们不应该接受低劣的linux移植游戏" tabindex="-1">为什么我们不应该接受低劣的Linux移植游戏 <a class="header-anchor" href="#为什么我们不应该接受低劣的linux移植游戏" aria-label="Permalink to “为什么我们不应该接受低劣的Linux移植游戏”">​</a></h1><p>由于最近The Witcher 2的惨败，我想写下些想法，为什么我们不应该接受来自开发人员的品质低劣的移植游戏。</p><p>最近几年在我们的Linux游戏库里面有如此多游戏，以至于你现在可以看到来自Linux玩家的评论“我们已经有很多游戏了！”可能这些声音来自很多像你一样的人。感谢Valve 和 Steam，之前我们从来没有得到过这么多的开发者的关注。</p><p>同样由于开发者的推进，我们看见了伴随而来的各种移植游戏，坦率地说，它们的质量十分的低劣，或者说对于大多数人们来说根本不值得去看一眼。</p><p>现在的问题就是，如果我们继续接受这种低水平质量的移植，Linux就会赢得一个游戏质量水平低的名声。请认真考虑一下这样的后果吧！</p><p>再想象一下，如果那些AAA级的开发者给Linux推送了大量游戏，其中使用了The Witcher2 移植所用的“eON”技术。看起来就像我们有了大量开发者，突然之间Linux有很多大牌游戏了。然后你可以看见大量的人尝试Linux，却发现它们的游戏在同等硬件之下却有着糟糕的画面，就会给他们一个印象，Linux对游戏不友好。这对我们所有人都很糟糕。</p><p>我已经看见许多人说“这个工具包用于移植没关系？”。这在我的眼里看来是一个非常天真的想法。当然，这有关系， 它意味Linux的游戏里面的光线和白天的不同品质。这就直接追溯到我上面关于Linux游戏的观点上了。</p><p>你可以坚持说工具包没有关系，而且使用任何一个你想用的比较/类比的效果，但如果工具包是导致问题的根源，就像我们说的计算机占用了99%的处理能力的软件一样，是的，它当然有关系！</p><p>如今，我已经看见许多来自其他主流网站发表的评论，“我们应该接受它们并且作感谢状，我们毕竟拥有了它们”。那些都是鼠目寸光的人们说的胡话！</p><p><img src="http://www.gamingonlinux.com/uploads/articles/article_images/1401025331gol2.jpg" alt=""></p><p>想想，那些开发者和发行商看到那些低劣的Linux移植游戏也能被接受时，他们的脑里只有钱。消费者对Linux游戏的感知就会进一步恶化，就是因为这些低劣的移植品。</p>',11)),e("p",null,[t[1]||(t[1]=n("我可以接受这些来自开发者的移植，毕竟是我运营着这个网站（ ",-1)),l(i,{href:"http://www.gamingonlinux.com/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.gamingonlinux.com/",-1)])]),_:1}),t[2]||(t[2]=n(" ）。但是，如果我作为一个消费者不愿意为在windows运行挺好的游戏买单，而却为在Linux慢得像蜗牛一样的游戏买单？我会么？你会么？",-1))]),t[15]||(t[15]=e("p",null,"最后附加的一点：你绝不应该攻击一个试图在社区里面解决问题的开发者，这样是不可以的。反馈是很好，骂人却是很幼稚的，这会使得Linux看起来更糟。",-1)),t[16]||(t[16]=e("hr",null,null,-1)),e("p",null,[t[4]||(t[4]=n("via: ",-1)),l(i,{href:"http://www.gamingonlinux.com/articles/why-we-shouldnt-accept-bad-linux-ports.3765"},{default:o(()=>[...t[3]||(t[3]=[n("http://www.gamingonlinux.com/articles/why-we-shouldnt-accept-bad-linux-ports.3765",-1)])]),_:1})]),e("p",null,[t[7]||(t[7]=n("译者：",-1)),l(i,{href:"http://www.vicyu.net"},{default:o(()=>[...t[5]||(t[5]=[n("Vic020",-1)])]),_:1}),t[8]||(t[8]=n(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=n("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原创翻译，",-1)),l(i,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[n("Linux中国",-1)])]),_:1}),t[13]||(t[13]=n(" 荣誉推出",-1))])])}const A=p(x,[["render",d]]);export{h as __pageData,A as default};
